class ProfileModel {  int? status;  Data? data;  String? message;  ProfileModel({this.status, this.data, this.message});  ProfileModel.fromJson(Map<String, dynamic> json) {    status = json['status'];    data = json['data'] != null ? new Data.fromJson(json['data']) : null;    message = json['message'];  }  Map<String, dynamic> toJson() {    final Map<String, dynamic> data = new Map<String, dynamic>();    data['status'] = this.status;    if (this.data != null) {      data['data'] = this.data!.toJson();    }    data['message'] = this.message;    return data;  }}class Data {  int? id;  String? fullname;  String? email;  String? countryCode;  String? phoneNumber;  String? gender;  String? birthDate;  String? profileImage;  String? notificationStatus;  String? country;  String? city;  String? address;  String? address2;  Data(      {this.id,      this.fullname,      this.email,      this.countryCode,      this.phoneNumber,      this.gender,      this.birthDate,      this.profileImage,      this.notificationStatus,      this.country,      this.city,      this.address,      this.address2});  Data.fromJson(Map<String, dynamic> json) {    id = json['id'];    fullname = json['fullname'];    email = json['email'];    countryCode = json['country_code'];    phoneNumber = json['phone_number'];    gender = json['gender'];    birthDate = json['birth_date'];    profileImage = json['profile_image'];    notificationStatus = json['notification_status'];    country = json['country'];    city = json['city'];    address = json['address'];    address2 = json['address2'];  }  Map<String, dynamic> toJson() {    final Map<String, dynamic> data = new Map<String, dynamic>();    data['id'] = this.id;    data['fullname'] = this.fullname;    data['email'] = this.email;    data['country_code'] = this.countryCode;    data['phone_number'] = this.phoneNumber;    data['gender'] = this.gender;    data['birth_date'] = this.birthDate;    data['profile_image'] = this.profileImage;    data['notification_status'] = this.notificationStatus;    data['country'] = this.country;    data['city'] = this.city;    data['address'] = this.address;    data['address2'] = this.address2;    return data;  }}